const NL = String.fromCharCode(10);
const roster = [
  { name: 'Kristina Deininger-Knapp', soll: '9-15', aliases: ['kristina deininger-knapp','kristina knapp'] },
  { name: 'Timo Müllerschön', soll: '9-15', aliases: ['timo müllerschön','timo muellerschön','timo müllerschoen'] },
  { name: 'Martin Keller', soll: '9-12', aliases: ['martin keller'] },
  { name: 'Tanja Becker', soll: '9-12', aliases: ['tanja becker'] },
  { name: 'Sascha Weingärtner', soll: '9-12', aliases: ['sascha','sascha weingärtner','sascha weingaertner'] },
  { name: 'Raphael Kroul', soll: '9-12', aliases: ['raphael kroul','rkroul','raphaels iphone'] },
  { name: 'Luca-Enrico Fauth', soll: '9-12', aliases: ['luca fauth','luca-enrico fauth','luca enrico fauth'] },
  { name: 'Sandro Röhricht', soll: '9-12', aliases: ['sandro röhricht','sandro roehricht'] },
  { name: 'Daniel Peukert', soll: '9-12', aliases: ['daniel peukert'] },
];
const ignore = ['timo merz','iphone von timo','timo-merz@web.de','meral celik'];
const norm = (s) => (s||'').toString().trim().toLowerCase().replace(/\s+/g,' ');
const aliasMap = {};
for (const p of roster) for (const a of p.aliases) aliasMap[norm(a)] = p;
const ignoreSet = new Set(ignore.map(norm));
const sollWindow = { '9-12': [7,10], '9-15': [7,13] };
function isoWeek(dstr){ const d=new Date(dstr+'T00:00:00Z'); const day=(d.getUTCDay()+6)%7; d.setUTCDate(d.getUTCDate()-day+3); const ft=new Date(Date.UTC(d.getUTCFullYear(),0,4)); const fd=(ft.getUTCDay()+6)%7; ft.setUTCDate(ft.getUTCDate()-fd+3); return 1+Math.round((d.getTime()-ft.getTime())/(7*86400000)); }
const rows = [];
for (const item of $input.all()) { const parts=(item.json&&item.json.participants)||[]; for (const p of parts){ if(!p.join_time) continue; rows.push({ name:p.name||'', join:new Date(p.join_time), leave:p.leave_time?new Date(p.leave_time):new Date(p.join_time) }); } }
const berlinDate=(d)=>new Date(d.getTime()+2*3600*1000).toISOString().slice(0,10);
const fmtBerlin=(ms)=>new Date(ms+2*3600*1000).toISOString().slice(11,16);
const wochentage=['So','Mo','Di','Mi','Do','Fr','Sa'];
const meetingEnd={};
for (const r of rows){ const dt=berlinDate(r.join); const lv=r.leave.getTime(); if(!(dt in meetingEnd)||lv>meetingEnd[dt]) meetingEnd[dt]=lv; }
const byDate={};
for (const r of rows){ const nn=norm(r.name); if(ignoreSet.has(nn)) continue; const date=berlinDate(r.join); byDate[date]=byDate[date]||{persons:{},unknown:{}}; const person=aliasMap[nn]; if(person){ byDate[date].persons[person.name]=byDate[date].persons[person.name]||{person,sessions:[]}; byDate[date].persons[person.name].sessions.push([r.join,r.leave]); } else { byDate[date].unknown[r.name]=(byDate[date].unknown[r.name]||0)+1; } }
function minutesIn(sessions,ws,we){ let ivs=sessions.map(([s,e])=>[Math.max(s.getTime(),ws),Math.min(e.getTime(),we)]).filter(([s,e])=>e>s); ivs.sort((a,b)=>a[0]-b[0]); let total=0,cs=null,ce=null; for(const [s,e] of ivs){ if(cs===null){cs=s;ce=e;} else if(s<=ce){ce=Math.max(ce,e);} else {total+=ce-cs;cs=s;ce=e;} } if(cs!==null) total+=ce-cs; return Math.round(total/60000); }
function rawSpan(sessions){ let mn=null,mx=null; for(const [s,e] of sessions){ const st=s.getTime(),et=e.getTime(); if(mn===null||st<mn)mn=st; if(mx===null||et>mx)mx=et; } return [mn,mx]; }
const out=[];
for (const date of Object.keys(byDate).sort()){ const bucket=byDate[date]; const dayStart=new Date(date+'T00:00:00Z').getTime(); const mEnd=meetingEnd[date]; const anwesende=[]; const present=new Set();
  for (const key in bucket.persons){ const {person,sessions}=bucket.persons[key]; present.add(key); const [wsH,weH]=sollWindow[person.soll]; const ws=dayStart+wsH*3600*1000; const we=dayStart+weH*3600*1000; const effEnd=Math.min(we,mEnd); const erreichbar=Math.max(0,Math.round((effEnd-ws)/60000)); const min=minutesIn(sessions,ws,effEnd); const cov=erreichbar>0?min/erreichbar:0; const sp=rawSpan(sessions); const status=min<=0?'⚠️ Rücksprache':(cov>=0.6?'✅ erfüllt':'⚠️ Rücksprache'); anwesende.push({ name:person.name, soll:person.soll+' Uhr', von:fmtBerlin(sp[0]), bis:fmtBerlin(sp[1]), minuten:min, erreichbar_min:erreichbar, abdeckung:Math.round(cov*100)+'%', status }); }
  anwesende.sort((a,b)=>a.name.localeCompare(b.name));
  const abwesende=roster.filter(p=>!present.has(p.name)).map(p=>p.name);
  const rueck=anwesende.filter(a=>a.status.includes('Rücksprache')).map(a=>a.name);
  const unbekannt=Object.keys(bucket.unknown);
  const d=new Date(date+'T12:00:00Z'); const wt=wochentage[d.getUTCDay()];
  const pp=date.split('-'); const dmy=pp[2]+'.'+pp[1]+'.'+pp[0];
  const lines=anwesende.map(a=>a.name+' ('+a.soll+'): '+a.von+'–'+a.bis+' · '+a.minuten+' Min · '+a.abdeckung+' · '+a.status);
  const anwesenheit_text='Meeting-Ende: '+fmtBerlin(mEnd)+NL+lines.join(NL);
  out.push({ json: { datum:date, wochentag:wt, kurstag:wt+', '+dmy, kw:isoWeek(date), meeting_ende:fmtBerlin(mEnd), anwesend_anzahl:anwesende.length, teilnehmer_gesamt:roster.length, abwesend_text:abwesende.length?abwesende.join(', '):'—', ruecksprache_text:rueck.length?rueck.join(', '):'—', anwesenheit_text, anwesende, abwesende, ruecksprache:rueck, unbekannt } }); }
return out;
